package dev.mando;
import org.bukkit.configuration.file.YamlConfiguration;import java.io.*;import java.time.*;import java.util.*;
public final class MailManager{private final MandoPlugin plugin;private final File file;private final YamlConfiguration y;public MailManager(MandoPlugin p){plugin=p;file=new File(p.getDataFolder(),"mail.yml");y=YamlConfiguration.loadConfiguration(file);}public synchronized String send(UUID from,String fromName,UUID to,String toName,String text){String base=to+".messages";List<Map<?,?>> old=y.getMapList(base);if(old.size()>=50)return "El buzón está lleno.";List<Map<String,Object>> list=new ArrayList<>();for(Map<?,?> x:old){Map<String,Object> n=new LinkedHashMap<>();x.forEach((k,v)->n.put(String.valueOf(k),v));list.add(n);}Map<String,Object> m=new LinkedHashMap<>();m.put("from",from.toString());m.put("from-name",fromName);m.put("sent",Instant.now().toString());m.put("read",false);m.put("text",text);list.add(m);y.set(base,list);saveNow();return "Mensaje enviado a "+toName+".";}public int total(UUID id){return y.getMapList(id+".messages").size();}public int unread(UUID id){int n=0;for(Map<?,?> m:y.getMapList(id+".messages"))if(!Boolean.TRUE.equals(m.get("read")))n++;return n;}public synchronized void saveNow(){try{file.getParentFile().mkdirs();y.save(file);}catch(IOException ex){plugin.getLogger().severe("Mail save: "+ex.getMessage());}}}
